import React from "react";
import "./Weather.css";
import SearchForm from "./SearchForm";
import axios from "axios"


export default function Weather(){

function handleResponse(response){
    console.log(response.data)
  }

  let city = "Pretoria";
  let apiKey = "bd75f0b07t2b8413f599c23a504017fo";
  let apiUrl = `https://api.shecodes.io/weather/v1/current?query=${city}&key=${apiKey}&units=metric`;
  axios.get(apiUrl).then(handleResponse);

    return( <div className="weather">
         <SearchForm />
        <h1> Pretoria </h1>
        <ul>
        <li>South Africa</li>
        <li>Wednesday 07:00 AM</li>
      <li>Sunny</li></ul>
          <div className="row">
            <div className="col-6">
                <div className="clearfix">

<img src="https://www.gstatic.com/weather/conditions/v1/svg/sunny_light.svg" alt="Sunny" className="image float-start"/>
<span className="temperature float-start">30</span>
<span className="units float-start">ºC</span>
            </div> </div>

            <div className="col-6">
              <ul>
                <li>Precipitation 15%</li>
                <li>Humidity: 60%</li>
                <li>Wind: 10 km/h</li>
              </ul> </div>

              </div> </div> )
}
